/* Generated from observatory.astrale-theme.json. Consumer-owned after installation. */
:root,
[data-ui-preset='observatory'],
[data-ui-theme='observatory'] {
  color-scheme: light;
  --ui-background: oklch(0.985 0.006 82);
  --ui-foreground: oklch(0.19 0.02 255);
  --ui-card: oklch(0.998 0.002 82);
  --ui-card-foreground: oklch(0.19 0.02 255);
  --ui-popover: oklch(1 0 0);
  --ui-popover-foreground: oklch(0.19 0.02 255);
  --ui-primary: oklch(0.36 0.14 251);
  --ui-primary-foreground: oklch(0.985 0.006 82);
  --ui-secondary: oklch(0.94 0.018 82);
  --ui-secondary-foreground: oklch(0.19 0.02 255);
  --ui-muted: oklch(0.955 0.008 82);
  --ui-muted-foreground: oklch(0.49 0.028 255);
  --ui-accent: oklch(0.9 0.07 78);
  --ui-accent-foreground: oklch(0.27 0.04 255);
  --ui-destructive: oklch(0.45 0.19 28);
  --ui-destructive-foreground: oklch(0.985 0 0);
  --ui-border: oklch(0.87 0.018 82);
  --ui-input: oklch(0.88 0.016 82);
  --ui-ring: oklch(0.705 0.015 286.067);
  --ui-chart-1: oklch(0.58 0.18 251);
  --ui-chart-2: oklch(0.68 0.16 165);
  --ui-chart-3: oklch(0.73 0.17 78);
  --ui-chart-4: oklch(0.63 0.19 28);
  --ui-chart-5: oklch(0.58 0.15 315);
  --ui-sidebar: oklch(0.998 0.002 82);
  --ui-sidebar-foreground: oklch(0.19 0.02 255);
  --ui-sidebar-primary: oklch(0.36 0.14 251);
  --ui-sidebar-primary-foreground: oklch(0.985 0.006 82);
  --ui-sidebar-accent: oklch(0.9 0.07 78);
  --ui-sidebar-accent-foreground: oklch(0.27 0.04 255);
  --ui-sidebar-border: oklch(0.87 0.018 82);
  --ui-sidebar-ring: oklch(0.705 0.015 286.067);
  --ui-radius: 0.7rem;
  --ui-radius-panel: 1rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Avenir Next', 'Segoe UI Variable', ui-sans-serif, sans-serif;
  --ui-font-heading: 'Iowan Old Style', 'Palatino Linotype', ui-serif, serif;
  --ui-font-mono: 'SFMono-Regular', 'Cascadia Code', ui-monospace, monospace;
  --ui-shadow-control: 0 1px 2px oklch(0.19 0.02 255 / 0.08);
  --ui-shadow-panel: 0 18px 55px oklch(0.19 0.02 255 / 0.1);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}

:root.dark,
[data-ui-preset='observatory'].dark,
[data-ui-theme='observatory'].dark {
  color-scheme: dark;
  --ui-background: oklch(0.15 0.02 255);
  --ui-foreground: oklch(0.95 0.008 82);
  --ui-card: oklch(0.19 0.024 255);
  --ui-card-foreground: oklch(0.95 0.008 82);
  --ui-popover: oklch(0.18 0.024 255);
  --ui-popover-foreground: oklch(0.95 0.008 82);
  --ui-primary: oklch(0.76 0.13 250);
  --ui-primary-foreground: oklch(0.15 0.02 255);
  --ui-secondary: oklch(0.25 0.025 255);
  --ui-secondary-foreground: oklch(0.95 0.008 82);
  --ui-muted: oklch(0.23 0.02 255);
  --ui-muted-foreground: oklch(0.7 0.025 82);
  --ui-accent: oklch(0.38 0.08 78);
  --ui-accent-foreground: oklch(0.96 0.008 82);
  --ui-destructive: oklch(0.78 0.16 28);
  --ui-destructive-foreground: oklch(0.98 0 0);
  --ui-border: oklch(0.3 0.025 255);
  --ui-input: oklch(0.29 0.025 255);
  --ui-ring: oklch(0.552 0.016 285.938);
  --ui-chart-1: oklch(0.7 0.16 250);
  --ui-chart-2: oklch(0.72 0.14 165);
  --ui-chart-3: oklch(0.76 0.16 78);
  --ui-chart-4: oklch(0.72 0.17 28);
  --ui-chart-5: oklch(0.7 0.14 315);
  --ui-sidebar: oklch(0.19 0.024 255);
  --ui-sidebar-foreground: oklch(0.95 0.008 82);
  --ui-sidebar-primary: oklch(0.76 0.13 250);
  --ui-sidebar-primary-foreground: oklch(0.15 0.02 255);
  --ui-sidebar-accent: oklch(0.38 0.08 78);
  --ui-sidebar-accent-foreground: oklch(0.96 0.008 82);
  --ui-sidebar-border: oklch(0.3 0.025 255);
  --ui-sidebar-ring: oklch(0.552 0.016 285.938);
  --ui-radius: 0.7rem;
  --ui-radius-panel: 1rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Avenir Next', 'Segoe UI Variable', ui-sans-serif, sans-serif;
  --ui-font-heading: 'Iowan Old Style', 'Palatino Linotype', ui-serif, serif;
  --ui-font-mono: 'SFMono-Regular', 'Cascadia Code', ui-monospace, monospace;
  --ui-shadow-control: 0 1px 2px oklch(0.19 0.02 255 / 0.08);
  --ui-shadow-panel: 0 18px 55px oklch(0.19 0.02 255 / 0.1);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}
